const input = $input.first().json;
const job = input.job ?? input;
if (job.kind !== 'generate_content' || !job.id || !job.client_id || !job.target_id || !job.leaseToken) throw new Error('Contrato generate_content v1 invalido');
return [{ json: { schemaVersion: 1, job } }];

const job = $('Validar trabajo').first().json.job;
const context = $input.first().json;
const raw = job.payload?.generatedContent ?? job.payload?.aiOutput;
if (!raw || typeof raw.title !== 'string' || (!raw.bodyHtml && !raw.bodyText)) throw new Error('Inserta los nodos IA del workflow original y entrega payload.generatedContent');
const content = { contentId: raw.contentId ?? job.id, title: raw.title.trim(), bodyHtml: raw.bodyHtml ?? null, bodyText: raw.bodyText ?? null, excerpt: raw.excerpt ?? null, seo: raw.seo ?? {}, promptVersion: raw.promptVersion ?? 'inficon-generate-v1', sourceReferences: Array.isArray(raw.sourceReferences) ? raw.sourceReferences : [] };
const draft = job.payload?.wordpressDraft;
const event = draft ? { schemaVersion: 1, clientId: job.client_id, entityType: 'content', entityId: content.contentId, eventType: 'wordpress.draft_created', sourceEventId: draft.eventId ?? null, occurredAt: draft.occurredAt ?? new Date().toISOString(), payload: { siteKey: draft.siteKey ?? null, postId: draft.postId ?? null, editUrl: draft.editUrl ?? null, status: 'draft' } } : { schemaVersion: 1, clientId: job.client_id, entityType: 'content', entityId: content.contentId, eventType: 'content.generated', sourceEventId: `generate:${job.id}`, occurredAt: new Date().toISOString(), payload: { workflowVersion: 1, timezone: context.settings?.timezone ?? 'Europe/Madrid' } };
return [{ json: { schemaVersion: 1, clientId: job.client_id, status: 'succeeded', content, result: { workflowVersion: 1, wordpressStatus: draft ? 'draft' : null }, event, leaseToken: job.leaseToken, jobId: job.id } }];
